from typing import Any, Callable, Dict, List

_event_handlers: Dict[str, List[Callable[..., Any]]] = {}


def subscribe(event_name: str, handler: Callable[..., Any]) -> None:
    handlers = _event_handlers.setdefault(event_name, [])
    handlers.append(handler)


def publish(event_name: str, payload: Any) -> None:
    for handler in _event_handlers.get(event_name, []):
        handler(payload)











